// Package test implements the `test` template-function namespace.
//
// The semantics mirror the observed behaviour of the reference gomplate
// binary, including exact error texts.
package test

import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

// Funcs is the namespace value returned by NS.
type Funcs struct{}

// NS returns the test namespace: a pointer to a struct whose methods are
// the namespace functions.
func NS() any {
	return &Funcs{}
}

// Aliases returns the top-level alias functions for this namespace.
func Aliases() map[string]any {
	f := &Funcs{}
	return map[string]any{
		"assert":   f.Assert,
		"fail":     f.Fail,
		"isKind":   f.IsKind,
		"kind":     f.Kind,
		"required": f.Required,
		"ternary":  f.Ternary,
	}
}

// Assert fails template generation unless the value is truthy.
func (Funcs) Assert(args ...any) (string, error) {
	if len(args) > 2 {
		return "", fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}
	// Deliberately index before the length check: with zero args this
	// panics with "runtime error: index out of range [-1]", which is what
	// the reference binary produces.
	in := args[len(args)-1]
	message := ""
	if len(args) == 2 {
		m, ok := args[0].(string)
		if !ok {
			return "", fmt.Errorf("at <1>: expected string; found %T", args[0])
		}
		message = m
	}
	if !toBool(in) {
		if message != "" {
			return "", fmt.Errorf("assertion failed: %s", message)
		}
		return "", errors.New("assertion failed")
	}
	return "", nil
}

// Fail causes template generation to fail immediately.
func (Funcs) Fail(args ...any) (string, error) {
	if len(args) > 1 {
		return "", fmt.Errorf("wrong number of args: want 0 or 1, got %d", len(args))
	}
	message := ""
	if len(args) == 1 {
		message = toString(args[0])
	}
	if message != "" {
		return "", fmt.Errorf("template generation failed: %s", message)
	}
	return "", errors.New("template generation failed")
}

// IsKind reports whether value is of the given kind. The special kind
// "number" matches any numeric kind.
func (f Funcs) IsKind(kind string, value any) bool {
	if kind == "number" {
		switch reflect.ValueOf(value).Kind() {
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64,
			reflect.Float32, reflect.Float64:
			return true
		}
		return false
	}
	return f.Kind(value) == kind
}

// Kind reports the reflect kind of the value as a lower-case string.
func (Funcs) Kind(value any) string {
	return reflect.ValueOf(value).Kind().String()
}

// Required passes the value through if it's non-nil and non-empty,
// otherwise template generation fails with the given message.
func (Funcs) Required(args ...any) (any, error) {
	var message string
	var value any
	switch len(args) {
	case 1:
		value = args[0]
	case 2:
		m, ok := args[0].(string)
		if !ok {
			return nil, fmt.Errorf("at <1>: expected string; found %T", args[0])
		}
		message = m
		value = args[1]
	default:
		return nil, fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}

	empty := value == nil
	if s, ok := value.(string); ok && s == "" {
		empty = true
	}
	if empty {
		if message != "" {
			return nil, errors.New(message)
		}
		return nil, errors.New("can not render template: a required value was not set")
	}
	return value, nil
}

// Ternary returns trueValue if condition is truthy, falseValue otherwise.
func (Funcs) Ternary(trueValue, falseValue, condition any) any {
	if toBool(condition) {
		return trueValue
	}
	return falseValue
}

// toBool converts a value to a boolean. Booleans pass through; strings are
// parsed leniently (strconv.ParseBool, then integer/float parsing where
// only the value 1 is true, then a case-insensitive "yes"); numbers are
// true only when equal to 1. Everything else is false.
func toBool(v any) bool {
	switch n := v.(type) {
	case bool:
		return n
	case string:
		if b, err := strconv.ParseBool(n); err == nil {
			return b
		}
		if i, err := strconv.ParseInt(n, 0, 64); err == nil {
			return i == 1
		}
		if f, err := strconv.ParseFloat(n, 64); err == nil {
			return f == 1
		}
		return strings.EqualFold(n, "yes")
	case int:
		return n == 1
	case int8:
		return n == 1
	case int16:
		return n == 1
	case int32:
		return n == 1
	case int64:
		return n == 1
	case uint:
		return n == 1
	case uint8:
		return n == 1
	case uint16:
		return n == 1
	case uint32:
		return n == 1
	case uint64:
		return n == 1
	case float32:
		return n == 1
	case float64:
		return n == 1
	}
	return false
}

// toString converts a value to a string for failure messages: nil becomes
// "nil", strings pass through, everything else uses fmt's %v.
func toString(v any) string {
	if v == nil {
		return "nil"
	}
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", v)
}

package test

import (
	"bytes"
	"strings"
	"testing"
	"text/template"
)

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"test": func() any { return NS() }}
	for name, fn := range Aliases() {
		fmap[name] = fn
	}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	err = tt.Execute(&buf, map[string]any{"Env": map[string]string{}})
	return buf.String(), err
}

// renderCase describes one template rendering expectation. For success
// cases want is the exact output; for failure cases wantErr is the exact
// error text the function must return (the substring after
// "error calling <Name>: " in the reference binary's output).
type renderCase struct {
	name    string
	tmpl    string
	want    string
	wantErr string
}

func runCases(t *testing.T, cases []renderCase) {
	t.Helper()
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			out, err := render(t, c.tmpl)
			if c.wantErr != "" {
				if err == nil {
					t.Fatalf("expected error %q, got output %q", c.wantErr, out)
				}
				if !strings.HasSuffix(err.Error(), ": error calling "+errCallName(c.tmpl)+": "+c.wantErr) &&
					!strings.Contains(err.Error(), ": "+c.wantErr) {
					t.Errorf("error %q does not contain expected text %q", err.Error(), c.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if out != c.want {
				t.Errorf("got %q, want %q", out, c.want)
			}
		})
	}
}

// errCallName is unused for strict matching; error assertions use Contains
// on the exact function error text, so this just aids the suffix check.
func errCallName(tmpl string) string { return "" }

func TestAssert(t *testing.T) {
	runCases(t, []renderCase{
