package test

import (
	"encoding/json"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"testing"
)

// TestAgainstReferenceBinary renders a sample of templates with both this
// package and the reference gomplate binary at /workspace/executable and
// compares results byte-for-byte (stdout for successes, the exact
// "error calling <Name>: <text>" portion for failures). It is skipped when
// the reference binary is not present.
func TestAgainstReferenceBinary(t *testing.T) {
	if _, err := os.Stat("/workspace/executable"); err != nil {
		t.Skip("reference binary not available")
	}

	templates := []string{
		// doc examples
		`{{ assert (eq "foo" "bar") }}`,
		`{{ assert "something horrible happened" false }}`,
		`{{ fail }}`,
		`{{ test.Fail "something is wrong!" }}`,
		`{{ if isKind "string" "hello world" }}hello world is a string{{ end }}`,
		`{{ kind "hello world" }}`,
		`{{ ternary "FOO" "BAR" false }}`,
		`{{ ternary "FOO" "BAR" "yes" }}`,
		// probed edge cases
		`{{ assert true }}`,
		`{{ assert 1 }}`,
		`{{ assert 0 }}`,
		`{{ assert -1 }}`,
		`{{ assert 1.5 }}`,
		`{{ assert "0x1" }}`,
		`{{ assert "1e0" }}`,
		`{{ assert " true " }}`,
		`{{ assert }}`,
		`{{ assert 1 2 3 }}`,
		`{{ assert true true }}`,
		`{{ assert nil false }}`,
		`{{ fail "" }}`,
		`{{ fail 42 }}`,
		`{{ fail 2.0 }}`,
		`{{ fail nil }}`,
		`{{ fail "a" "b" }}`,
		`{{ isKind "number" 4.2 }}`,
		`{{ isKind "number" "42" }}`,
		`{{ isKind "invalid" nil }}`,
		`{{ isKind "bogus" 1 }}`,
		`{{ isKind 42 42 }}`,
		`{{ kind nil }}`,
		`{{ kind }}`,
		`{{ required "msg" "val" }}`,
		`{{ required "msg" "" }}`,
		`{{ required "msg" 0 }}`,
		`{{ required "msg" false }}`,
		`{{ required "msg" nil }}`,
		`{{ required }}`,
		`{{ required "" "" }}`,
		`{{ required 42 "" }}`,
		`{{ required "a" "b" "c" }}`,
		`{{ ternary 1 2 }}`,
		`{{ ternary "A" "B" 2 }}`,
		`{{ test.Ternary "x" "y" "TRUE" }}`,
	}

	errRe := regexp.MustCompile(`error calling \w+: (.*)$`)
	for _, tmpl := range templates {
		t.Run(tmpl, func(t *testing.T) {
			cmd := exec.Command("/workspace/executable", "-i", tmpl)
			var stdout, stderr strings.Builder
			cmd.Stdout = &stdout
			cmd.Stderr = &stderr
			runErr := cmd.Run()

			myOut, myErr := render(t, tmpl)

			if runErr == nil {
				if myErr != nil {
					t.Fatalf("reference succeeded with %q, mine failed: %v", stdout.String(), myErr)
				}
				if myOut != stdout.String() {
					t.Errorf("output mismatch: reference %q, mine %q", stdout.String(), myOut)
				}
				return
			}

			// reference failed; extract the exact function error text
			var logLine struct {
				Err string `json:"err"`
			}
			if err := json.Unmarshal([]byte(strings.TrimSpace(stderr.String())), &logLine); err != nil {
				t.Fatalf("reference failed with unparseable stderr %q: %v", stderr.String(), err)
			}
			m := errRe.FindStringSubmatch(logLine.Err)
			if m == nil {
				t.Fatalf("no 'error calling' text in reference error %q", logLine.Err)
			}
			refText := m[1]

			if myErr == nil {
				t.Fatalf("reference failed with %q, mine succeeded with %q", refText, myOut)
			}
			mm := errRe.FindStringSubmatch(myErr.Error())
			if mm == nil {
				// engine-generated errors (arity, type) have no
				// "error calling" prefix; compare the tail instead
				if !strings.HasSuffix(logLine.Err, myErr.Error()) {
					t.Errorf("error mismatch:\nreference: %q\nmine:      %q", logLine.Err, myErr.Error())
				}
				return
			}
			if mm[1] != refText {
				t.Errorf("error text mismatch: reference %q, mine %q", refText, mm[1])
			}
		})
	}
}

